/* @autogenerated */
import { signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { provideRouter } from '@angular/router';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { AppStateService } from '@shared/context/state/app-state.service';
import { ErrorModalComponent, ErrorModalData } from './error-modal.component';

describe('ErrorModalComponent', () => {
  function setup(data: ErrorModalData) {
    const dialogRef = { close: jasmine.createSpy('close') } as unknown as MatDialogRef<ErrorModalComponent>;
    TestBed.configureTestingModule({
      imports: [ErrorModalComponent, TranslocoTestingModule.forRoot({ langs: {} })],
      providers: [
        provideRouter([]),
        { provide: MatDialogRef, useValue: dialogRef },
        { provide: MAT_DIALOG_DATA, useValue: data },
        { provide: AppStateService, useValue: { language: signal('es'), tenant: signal('main') } },
      ],
    });
    const fixture = TestBed.createComponent(ErrorModalComponent);
    fixture.detectChanges();
    const el = fixture.nativeElement as HTMLElement;
    const actions = () =>
      Array.from(el.querySelectorAll<HTMLElement>('mat-dialog-actions button, mat-dialog-actions a'));
    return { el, dialogRef, actions };
  }

  it('uses the error title as the dialog title, without repeating it in the content', () => {
    const { el } = setup({ error: { status: 404 } });

    expect(el.querySelector('[mat-dialog-title]')!.textContent).toContain('errors.page.error_404.title');
    expect(el.querySelector('mat-dialog-content h2')).toBeNull();
  });

  it('closes with a visible button', () => {
    const { dialogRef, actions } = setup({ error: { status: 500 } });

    const close = actions().find((b) => b.textContent!.includes('common.notify.close'))!;
    close.click();

    expect(dialogRef.close).toHaveBeenCalled();
  });

  it('links home with language and tenant, closing the dialog', () => {
    const { el, dialogRef } = setup({ error: { status: 404 } });

    const home = el.querySelector<HTMLAnchorElement>('mat-dialog-actions a')!;
    expect(home.getAttribute('href')).toBe('/es/main');
    expect(el.querySelector('mat-dialog-content a')).toBeNull();
    home.click();

    expect(dialogRef.close).toHaveBeenCalled();
  });

  it('shows the sign-in button when the error offers it, and closes before signing in', () => {
    const login = jasmine.createSpy('login');
    const { dialogRef, actions } = setup({ error: { status: 401 }, login });

    const button = actions().find((b) => b.textContent!.includes('auth.unauthorized.login'))!;
    button.click();

    expect(dialogRef.close).toHaveBeenCalled();
    expect(login).toHaveBeenCalled();
  });

  it('hides the sign-in button otherwise', () => {
    const { actions } = setup({ error: { status: 401 } });

    expect(actions().some((b) => b.textContent!.includes('auth.unauthorized.login'))).toBeFalse();
  });
});
